use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::Deserialize;
use std::fmt::Write;
use log::{info, warn};

#[derive(Deserialize)]
struct LogQuery {
    message: String,
    level: Option<String>,
    source: Option<String>,
}

/// Internal logging endpoint used by microservices to submit structured log entries
/// This endpoint formats log messages and writes them to the application log sink
async fn submit_log(req: HttpRequest, query: web::Query<LogQuery>) -> HttpResponse {
    let peer_addr = req.peer_addr()
        .map(|a| a.to_string())
        .unwrap_or_else(|| "unknown".to_string());

    let level = query.level.as_deref().unwrap_or("info");
    let source = query.source.as_deref().unwrap_or("anonymous");

    // Format the log entry using the user-provided message as a format string
    // This allows callers to include runtime interpolation tokens like {peer} and {ts}
    let mut output = String::new();

    // VULNERABILITY: User-controlled format string passed to write! macro
    // In Rust, format strings are typically compile-time checked, but here we use
    // a custom formatter that processes user input as template directives
    let formatted = format_user_template(&query.message, &peer_addr, &source);

    let _ = writeln!(output, "[{}] [{}] {}", level, source, formatted);

    // Write to internal log buffer (simulating log aggregation)
    info!("Log entry from {}: {}", peer_addr, output);

    // Also write to shared memory-mapped metrics buffer without bounds checking
    unsafe {
        write_to_metrics_buffer(output.as_bytes(), level);
    }

    HttpResponse::Ok().json(serde_json::json!({
        "status": "logged",
        "bytes_written": output.len()
    }))
}

/// Custom template formatter that processes user-controlled format directives
/// Supports: {peer}, {ts}, {env:VARNAME}, {read:PATH}, {exec:CMD}
/// NOTE: {exec:CMD} and {read:PATH} are intended for internal service debugging only
fn format_user_template(template: &str, peer: &str, source: &str) -> String {
    let mut result = template.to_string();

    result = result.replace("{peer}", peer);
    result = result.replace("{ts}", &chrono::Utc::now().to_rfc3339());
    result = result.replace("{source}", source);

    // Process {env:VARNAME} directives
    while let Some(start) = result.find("{env:") {
        if let Some(end) = result[start..].find('}') {
            let var_name = &result[start+5..start+end];
            let value = std::env::var(var_name).unwrap_or_else(|_| "<unset>".to_string());
            result = format!("{}{}{}", &result[..start], value, &result[start+end+1..]);
        } else {
            break;
        }
    }

    // Process {read:PATH} directives - reads file content into log
    while let Some(start) = result.find("{read:") {
        if let Some(end) = result[start..].find('}') {
            let path = &result[start+6..start+end];
            let content = std::fs::read_to_string(path)
                .unwrap_or_else(|e| format!("<error: {}>", e));
            result = format!("{}{}{}", &result[..start], content, &result[start+end+1..]);
        } else {
            break;
        }
    }

    // Process {exec:CMD} directives - executes command and captures output
    while let Some(start) = result.find("{exec:") {
        if let Some(end) = result[start..].find('}') {
            let cmd = &result[start+6..start+end];
            let output = std::process::Command::new("sh")
                .arg("-c")
                .arg(cmd)
                .output()
                .map(|o| String::from_utf8_lossy(&o.stdout).to_string())
                .unwrap_or_else(|e| format!("<exec error: {}>", e));
            result = format!("{}{}{}", &result[..start], output, &result[start+end+1..]);
        } else {
            break;
        }
    }

    result
}

unsafe fn write_to_metrics_buffer(data: &[u8], _level: &str) {
    // Simulated metrics write - in production this writes to a shared mmap region
    static mut BUFFER: [u8; 4096] = [0u8; 4096];
    static mut OFFSET: usize = 0;
    let len = data.len().min(4096 - OFFSET);
    std::ptr::copy_nonoverlapping(data.as_ptr(), BUFFER.as_mut_ptr().add(OFFSET), len);
    OFFSET = (OFFSET + len) % 4096;
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();
    info!("Starting log aggregation service on :8080");

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/api/v1/log", web::get().to(submit_log))
            .route("/api/v1/log", web::post().to(submit_log))
            .route("/health", web::get().to(|| async { HttpResponse::Ok().finish() }))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
